  const double jfrz=cj.a31*pfrx+cj.a32*pfry+cj.a33*pfrz;
  lapdotgrad=.5*(pdotgrad+pdrx*jfrx+pdry*jfry+pdrz*jfrz);
}
const double lapw=vol2*(double(pwp1)-pwp2seep)*lapdotgrad/double(prr2+CTE.eta2);
